import{z as B,x as A,o,c as i,q as s,j as t,D as E,d as l,s as r,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"load-use 气泡","description":"","frontmatter":{"title":"load-use 气泡","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/load-use-stall.md","filePath":"cs/load-use-stall.md","lastUpdated":1791413859000}'),p={name:"cs/load-use-stall.md"};function D(u,a,M,c,m,h){const d=A("Mermaid");return o(),i("div",null,[a[2]||(a[2]=s('<h1 id="load-use-气泡" tabindex="-1">load-use 气泡 <a class="header-anchor" href="#load-use-气泡" aria-label="Permalink to &quot;load-use 气泡&quot;">​</a></h1><div class="epigraph"><p>load 的数据在 MEM 结束才出现；紧接着的 ALU 若已进入 EX，旁路也晚了一拍，只能插入气泡。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/data-hazard-forward">上一课</a>用 EX/MEM 与 MEM/WB 旁路恢复了 ALU 对 ALU 的 RAW，并已经点名 load-use 要停一拍。本课不重画 mux。缺口是：那一拍气泡究竟冻哪几级、控制位如何变成 NOP，以及编译器调度为什么只能减少它、不能代替硬件检测。本课只把 load-use 停顿写成流水线控制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>lw x1, 0(x2)</code> 后紧跟 <code>add x3, x1, x4</code>。转发源在 MEM 末，使用者在下一拍的 EX 开头就要 ALU 输入。路径差一拍，旁路接不上。缺口不是再加一条从 MEM 到 EX 的导线——数据那时还不存在——而是<strong>在 ID 认出「前一条是 load 且 <code>rd</code> 命中本条 <code>rs</code>」时，让 IF/ID 保持，并向 ID/EX 写入空操作</strong>。</p><p>上一课把这条规则附在转发课里，容易让人以为停顿是转发失败的边角。五级整数核里，它是数据通路上唯一必须靠气泡的 RAW。</p><p><span class="marginnote">早期 MIPS 把 load 延迟暴露给软件：延迟槽里不得使用刚 load 的寄存器。当代核用硬件互锁，ISA 不再要求程序员填槽。</span></p><p><span class="marginnote">气泡可以类比传送带上的空托盘：货（load 的数据）还没到，先放一个空托盘占住一格往下走——它什么都不装，只是消耗一格传送带时间，保证后面的货到达时顺序不乱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检测：ID/EX 的 <code>MemRead</code> 为真，且其 <code>rd</code> 等于 ID 级指令的 <code>rs1</code> 或 <code>rs2</code>。成立则：PC 与 IF/ID 写使能关掉（取指与译码冻结），ID/EX 控制位清零（EX/MEM/WB 变成不写堆、不访存）。下一拍 load 进入 MEM，再下一拍走上一课的 MEM→EX 转发。</p>',10)),(o(),t(n,null,{default:E(()=>[r(d,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DET%5B%22ID%20%E6%A3%80%E5%87%BA%20load-use%22%5D%20--%3E%20FRZ%5B%22%E5%86%BB%E7%BB%93%20PC%20%E4%B8%8E%20IF%2FID%22%5D%0A%20%20DET%20--%3E%20BUB%5B%22ID%2FEX%20%E5%86%99%E5%85%A5%20NOP%20%E6%8E%A7%E5%88%B6%22%5D%0A%20%20BUB%20--%3E%20MEM%5B%22load%20%E8%BF%9B%E5%85%A5%20MEM%22%5D%0A%20%20MEM%20--%3E%20FWD%5B%22%E4%B8%8B%E4%B8%80%E6%8B%8D%20MEM%20%E6%97%81%E8%B7%AF%E5%88%B0%20EX%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"编译器可在 load 与使用者之间插入无关指令，使检测不触发。硬件仍必须对任意指令对正确；调度只改频率，不改语义。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：一拍 1 ns 的五级核，这一泡就白扔一个发射机会。若程序每 5 条指令撞上一次「load 后立即使用」，每 5 拍要多等 1 拍，CPI 从 1 涨到 1.2——整条程序慢约 20%，这就是编译器拼命把无关指令塞进 load 后面的原因。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"为什么 ALU 相关不用停、load 后使用必须停？差别只在结果出现的时刻：ALU 结果 EX 末就有，旁路接得上下一拍的 EX；load 的数据要等 MEM 末才回来，晚了整整一拍。",-1)),(o(),t(n,null,{default:E(()=>[r(d,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%A4%E6%9D%A1%20RAW%20%E8%B7%AF%E5%BE%84%E5%AF%B9%E6%AF%94%22%5D%20--%3E%20ALU%5B%22ALU%20%E7%BB%93%E6%9E%9C%E5%9C%A8%20EX%20%E6%9C%AB%E4%BA%A7%E7%94%9F%22%5D%0A%20%20ALU%20--%3E%20F1%5B%22EX%2FMEM%20%E6%97%81%E8%B7%AF%E6%8E%A5%E4%B8%8A%E4%B8%8B%E4%B8%80%E6%8B%8D%20EX%22%5D%0A%20%20F1%20--%3E%20NO%5B%22%E6%97%A0%E9%9C%80%E6%B0%94%E6%B3%A1%22%5D%0A%20%20Q%20--%3E%20LD%5B%22load%20%E6%95%B0%E6%8D%AE%E5%9C%A8%20MEM%20%E6%9C%AB%E6%89%8D%E5%87%BA%E7%8E%B0%22%5D%0A%20%20LD%20--%3E%20F2%5B%22%E4%B8%8B%E4%B8%80%E6%8B%8D%20EX%20%E5%BC%80%E5%A4%B4%E6%8E%A5%E4%B8%8D%E4%B8%8A%22%5D%0A%20%20F2%20--%3E%20BU%5B%22%E5%86%BB%E7%BB%93%E4%B8%80%E6%8B%8D%E7%AD%89%E6%95%B0%E6%8D%AE%22%5D%0A%20%20BU%20--%3E%20F3%5B%22%E9%9A%94%E4%B8%80%E6%8B%8D%E5%90%8E%20MEM%20%E6%97%81%E8%B7%AF%E6%8E%A5%E4%B8%8A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">初学者容易以为「转发装得多就能消灭一切停顿」。实际上旁路只是导线，变不出还不存在的数据：load-use 的差距是访存本身慢一拍，任何接线都救不了，只能等。这就是为什么它是五级核里唯一必须气泡的 RAW。</span></p><p>气泡占用一拍发射机会，CPI 加在数据停顿项上。与结构冒险的停顿同类：流水线寄存器被写成「什么也不做」，但对象是数据相关而不是端口不够。写回相（前半拍写堆）救不了 load-use：值根本还不在堆里。</p><p>多发射后，同一拍里可能有一条 load 和一条使用它的 ALU，窗口更大，停顿规则要按发射包重写。本课钉五级单发射：至多一拍。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理分支条件也依赖 load 的情况——那是控制冒险与数据冒险叠在一起，后课预测器仍要等操作数或把比较前移。也不引入缺失下继续：这里假定 MEM 一拍完成；cache 缺失会把这一拍变成许多拍，那是存储器层次的缺口。</p><p>后课默认：整数 ALU 相关用转发；load 后立即使用插入一拍气泡。谈到控制流，下一 PC 才是新缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>转发消除 ALU–ALU RAW；load-use 差一拍，必须互锁。</li><li>冻结取指/译码，向 EX 插入 NOP 控制，再走 MEM 旁路。</li><li>编译调度只降频率；硬件检测不能省。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V load-use hazard；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const C=B(p,[["render",D]]);export{f as __pageData,C as default};
